/* gemver.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;
  /* Capture the PolyBench loop bound once to avoid macro re-expansion
     and to make it available as a regular integer. */
  const int nPB = _PB_N;

#pragma scop

  /* 1. Rank-1 updates: A += u1*v1^T + u2*v2^T
   *
   * Optimization:
   * - Hoist u1[i] and u2[i] out of the inner loop.
   * - Use a row pointer Ai to improve cache locality and help
   *   the compiler vectorize the inner loop.
   * - The OpenMP pragma (ignored without -fopenmp) allows
   *   parallelization across rows, which are independent.
   */
#pragma omp parallel for schedule(static) if (nPB >= 64)
  for (i = 0; i < nPB; i++)
  {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE u1_i = u1[i];
    DATA_TYPE u2_i = u2[i];

    for (j = 0; j < nPB; j++)
    {
      Ai[j] += u1_i * v1[j] + u2_i * v2[j];
    }
  }

  /* 2. x = beta * A^T * y + z
   *
   * Original code:
   *   for (i = 0; i < _PB_N; i++)
   *     for (j = 0; j < _PB_N; j++)
   *       x[i] = x[i] + beta * A[j][i] * y[j];
   *   for (i = 0; i < _PB_N; i++)
   *     x[i] = x[i] + z[i];
   *
   * Optimization:
   * - We reorder the two loops to traverse A by contiguous rows:
   *       for (j) for (i) x[i] += beta * A[j][i] * y[j];
   * - For each fixed i, the sequence of updates over j is still
   *   j = 0, 1, ..., nPB-1, so the floating-point accumulation
   *   order for x[i] is unchanged; results remain bitwise identical.
   * - Using a row pointer Aj and precomputing beta * y[j] improves
   *   locality and reduces multiplications in the inner loop.
   */
  for (j = 0; j < nPB; j++)
  {
    DATA_TYPE *Aj = A[j];
    DATA_TYPE beta_yj = beta * y[j];

    for (i = 0; i < nPB; i++)
    {
      x[i] += beta_yj * Aj[i];
    }
  }

  /* Add z after the matrix-vector product, as in the original code. */
  for (i = 0; i < nPB; i++)
    x[i] += z[i];

  /* 3. w = alpha * A * x
   *
   * Original code:
   *   for (i = 0; i < _PB_N; i++)
   *     for (j = 0; j < _PB_N; j++)
   *       w[i] = w[i] +  alpha * A[i][j] * x[j];
   *
   * Optimization:
   * - Access A in row-major order via Ai = A[i].
   * - Accumulate into a scalar wi to reduce repeated memory
   *   traffic for w[i], then write it back once.
   * - Parallelize across rows i: each row computation is
   *   independent, so there are no data races.
   */
#pragma omp parallel for schedule(static) if (nPB >= 64)
  for (i = 0; i < nPB; i++)
  {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE wi = w[i];

    for (j = 0; j < nPB; j++)
    {
      wi += alpha * Ai[j] * x[j];
    }

    w[i] = wi;
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemver (n, alpha, beta,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(u1),
		 POLYBENCH_ARRAY(v1),
		 POLYBENCH_ARRAY(u2),
		 POLYBENCH_ARRAY(v2),
		 POLYBENCH_ARRAY(w),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y),
		 POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
