    DATA_TYPE sum = w_[i_local];

    for (int j_local = 0; j_local < _PB_N; j_local++)
      sum += alpha_ * Ai[j_local] * x_[j_local];

    w_[i_local] = sum;
  }

#pragma endscop
}


