  {
    const DATA_TYPE * restrict A_row = A_[i];
    const DATA_TYPE alpha_local = alpha;
    DATA_TYPE sum = w_[i];

    for (j = 0; j < _PB_N; j++)
      sum += alpha_local * A_row[j] * x_[j];

    w_[i] = sum;
  }

#pragma endscop
